<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {createCancelablePolling} from '../services/polling';
import AppDialog from './AppDialog.vue';

type Attachment={nome:string;bytes:number;hash:string};
type Preview={para:string;contato:string;cliente:string;cnpj:string;assunto:string;texto:string;html:string;versao:string;anexos:Attachment[]};
type Delivery={id:number;cliente_id:number;contato_id:number;numero_registro:string;versao:string;status:string;motivo:string|null;tentativas:number;erro:string|null;criado_em:string;atualizado_em:string;enviado_em:string|null;cliente:string;contato:string;email:string;aplicabilidade:string;tem_previa:boolean;snapshot:Preview|null;previsualizacao_hash:string|null};
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>;canManage:boolean}>();
const rows=ref<Delivery[]>([]),loading=ref(false),loaded=ref(false),error=ref(''),updated=ref(''),query=ref(''),status=ref(''),client=ref(''),contact=ref(''),selected=ref<Delivery|null>(null),downloadError=ref(''),downloading=ref<number|null>(null),confirmation=ref<'approve'|'cancel'|null>(null),confirmed=ref(false),saving=ref(false),actionError=ref(''),actionNotice=ref('');
const labels:Record<string,string>={bloqueado:'Bloqueado',preparando:'Preparando',revisao:'Aguardando revisão',na_fila:'Na fila',enviando:'Enviando',enviado:'Enviado',falhou:'Falhou',cancelado:'Cancelado',incerto:'Entrega incerta'};
const tone=(value:string)=>value==='enviado'?'success':['falhou','incerto'].includes(value)?'danger':['revisao','bloqueado','preparando','cancelado'].includes(value)?'warning':'info';
const clients=computed(()=>[...new Map(rows.value.map(item=>[item.cliente_id,item.cliente])).entries()].map(([id,name])=>({id,name})).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')));
const contacts=computed(()=>[...new Map(rows.value.map(item=>[item.contato_id,{name:item.contato,email:item.email}])).entries()].map(([id,value])=>({id,...value})).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')));
const visible=computed(()=>{const term=query.value.trim().toLocaleLowerCase('pt-BR');return rows.value.filter(item=>(!status.value||item.status===status.value)&&(!client.value||String(item.cliente_id)===client.value)&&(!contact.value||String(item.contato_id)===contact.value)&&(!term||[item.numero_registro,item.cliente,item.contato,item.email,item.versao,item.erro||'',item.motivo||''].join(' ').toLocaleLowerCase('pt-BR').includes(term)));});
const summary=computed(()=>({total:rows.value.length,revisao:rows.value.filter(item=>item.status==='revisao').length,fila:rows.value.filter(item=>['na_fila','enviando'].includes(item.status)).length,atencao:rows.value.filter(item=>['bloqueado','falhou','incerto'].includes(item.status)).length,enviados:rows.value.filter(item=>item.status==='enviado').length}));
function clear(){query.value='';status.value='';client.value='';contact.value='';}
function date(value:string|null){if(!value)return 'Ainda não enviado';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'Data indisponível':parsed.toLocaleString('pt-BR');}
function bytes(value:number){return new Intl.NumberFormat('pt-BR',{style:'unit',unit:'byte',unitDisplay:'narrow',maximumFractionDigits:0}).format(value);}
const canApprove=computed(()=>!!selected.value&&props.canManage&&selected.value.status==='revisao'&&!!selected.value.snapshot&&selected.value.snapshot.versao===selected.value.versao&&!!selected.value.previsualizacao_hash);
const canCancel=computed(()=>!!selected.value&&props.canManage&&!['enviando','enviado','preparando','cancelado'].includes(selected.value.status));
function close(){selected.value=null;downloadError.value='';downloading.value=null;confirmation.value=null;confirmed.value=false;actionError.value='';saving.value=false;}
function ask(action:'approve'|'cancel'){confirmation.value=action;confirmed.value=false;actionError.value='';}
async function applyAction(){const item=selected.value,action=confirmation.value;if(!item||!action||!confirmed.value||saving.value)return;saving.value=true;actionError.value='';try{if(action==='approve'){if(!item.previsualizacao_hash)throw new Error('Abra uma prévia atual antes de aprovar.');await props.request(`/api/contexto/envios/${item.id}/aprovar`,'POST',{previsualizacao_hash:item.previsualizacao_hash});actionNotice.value='Envio aprovado e colocado na fila.';}else{await props.request(`/api/contexto/envios/${item.id}/cancelar`,'POST',{});actionNotice.value='Cancelamento registrado pelo servidor.';}close();void polling.refresh();}catch(cause){actionError.value=(cause as Error).message||'Não foi possível atualizar o envio.';}finally{if(selected.value===item)saving.value=false;}}
async function downloadAttachment(index:number){const item=selected.value;if(!item||!item.snapshot||downloading.value!==null)return;downloading.value=index;downloadError.value='';try{const file=await props.download(`/api/contexto/envios/${item.id}/anexos/${index}`);if(selected.value!==item)return;const url=URL.createObjectURL(file.blob),link=document.createElement('a');link.href=url;link.download=item.snapshot.anexos[index].nome;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(cause){if(selected.value===item)downloadError.value=(cause as Error).message||'Não foi possível baixar o anexo.';}finally{if(selected.value===item)downloading.value=null;}}
const polling=createCancelablePolling({interval:15000,load:signal=>props.request<Delivery[]>('/api/contexto/envios','GET',undefined,signal),data:data=>{rows.value=data;loaded.value=true;error.value='';updated.value=new Date().toLocaleTimeString('pt-BR');},error:cause=>{error.value=(cause as Error).message||'Não foi possível consultar a fila de envios.';},busy:value=>{loading.value=value;}});
onMounted(()=>{void polling.refresh();});
onBeforeUnmount(()=>polling.stop());
</script>

<template><section class="deliveries-panel" aria-label="Fila de envios"><header class="deliveries-heading"><div><span class="eyebrow">Operação do escritório</span><h2>Fila de envios</h2><p>Consulte os destinatários preparados e os estados confirmados pelo servidor. Aprovações, cancelamentos e reprocessamentos são tratados nos próximos fluxos.</p></div><button type="button" class="secondary" :disabled="loading" @click="polling.refresh">Atualizar fila</button></header>
  <div class="delivery-summary" aria-label="Resumo da fila"><article><small>Total</small><strong>{{ summary.total }}</strong></article><article><small>Aguardando revisão</small><strong>{{ summary.revisao }}</strong></article><article><small>Na fila ou enviando</small><strong>{{ summary.fila }}</strong></article><article><small>Exigem atenção</small><strong>{{ summary.atencao }}</strong></article><article><small>Enviados</small><strong>{{ summary.enviados }}</strong></article></div>
  <div class="registry-controls"><label>Buscar envio, empresa ou destinatário<input v-model="query" type="search" placeholder="Documento, empresa ou e-mail"></label><label>Situação<select v-model="status"><option value="">Todas as situações</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label><label>Empresa<select v-model="client"><option value="">Todas as empresas</option><option v-for="item in clients" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></label><label>Destinatário<select v-model="contact"><option value="">Todos os destinatários</option><option v-for="item in contacts" :key="item.id" :value="String(item.id)">{{ item.name }} · {{ item.email }}</option></select></label></div>
  <div v-if="loaded" class="delivery-results"><p role="status">{{ visible.length }} de {{ rows.length }} envios nesta consulta.<span v-if="updated"> Última consulta: {{ updated }}.</span></p><button v-if="query||status||client||contact" type="button" class="secondary" @click="clear">Limpar filtros</button></div>
  <p v-if="actionNotice" role="status" class="delivery-action-notice">{{ actionNotice }}</p><p v-if="loading" role="status">Consultando fila de envios…</p><div v-if="error" role="alert"><p>{{ error }}</p><p>{{ loaded?'Os dados exibidos são da última consulta bem-sucedida.':'Nenhuma consulta concluída.' }} Uma nova tentativa ocorrerá automaticamente.</p><button type="button" class="secondary" :disabled="loading" @click="polling.refresh">Tentar novamente</button></div>
  <div v-if="loaded" class="registry-scroll"><table><caption>Envios do escritório</caption><thead><tr><th scope="col">Envio e documento</th><th scope="col">Empresa e destinatário</th><th scope="col">Situação</th><th scope="col">Atualizado em</th><th scope="col">Detalhe</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td><strong>#{{ item.id }} · {{ item.numero_registro }}</strong><small>Versão {{ item.versao }}{{ item.tem_previa?' · Prévia disponível':' · Sem prévia' }}</small></td><td><strong>{{ item.cliente }}</strong><small>{{ item.contato }} · {{ item.email }}</small></td><td><span class="status-badge" :data-tone="tone(item.status)">{{ labels[item.status]||item.status }}</span><small>Tentativas: {{ item.tentativas }}</small><small v-if="item.erro||item.motivo">{{ item.erro||item.motivo }}</small></td><td>{{ date(item.atualizado_em) }}<small v-if="item.enviado_em">Enviado: {{ date(item.enviado_em) }}</small></td><td><button type="button" class="secondary" :aria-label="'Ver detalhes do envio '+item.id" @click="selected=item">Ver detalhe</button></td></tr><tr v-if="!visible.length"><td colspan="5">{{ rows.length?'Nenhum envio corresponde aos filtros selecionados.':'Ainda não há envios preparados neste escritório.' }}</td></tr></tbody></table></div>
  <AppDialog v-if="selected" title="Detalhes do envio" :busy="downloading!==null||saving" @close="close"><header class="delivery-detail-heading"><div><span class="eyebrow">Envio #{{ selected.id }}</span><h3>{{ selected.numero_registro }}</h3><p>{{ selected.cliente }} · {{ selected.contato }}</p></div><span class="status-badge" :data-tone="tone(selected.status)">{{ labels[selected.status]||selected.status }}</span></header><div class="delivery-detail-grid"><article><small>Destinatário</small><p>{{ selected.email }}</p></article><article><small>Versão registrada</small><p class="delivery-version">{{ selected.versao }}</p></article><article><small>Aplicabilidade</small><p>{{ selected.aplicabilidade }}</p></article><article><small>Tentativas</small><p>{{ selected.tentativas }}</p></article></div><p v-if="selected.erro||selected.motivo" class="delivery-detail-warning">{{ selected.erro||selected.motivo }}</p><template v-if="selected.snapshot"><section aria-label="Prévia do envio"><h3>Prévia preparada</h3><p v-if="selected.snapshot.versao!==selected.versao" role="alert">A prévia pertence a outra versão. Atualize o envio antes de aprová-lo.</p><dl class="delivery-preview-meta"><dt>Para</dt><dd>{{ selected.snapshot.para }}</dd><dt>Assunto</dt><dd>{{ selected.snapshot.assunto }}</dd><dt>Hash da prévia</dt><dd class="delivery-version">{{ selected.previsualizacao_hash||'Indisponível' }}</dd></dl><h4>Mensagem</h4><pre class="delivery-preview-text">{{ selected.snapshot.texto }}</pre></section><section aria-label="Anexos preparados"><h3>Anexos preparados</h3><p v-if="!selected.snapshot.anexos.length">Não há anexos nesta prévia.</p><ul v-else class="delivery-attachments"><li v-for="(attachment,index) in selected.snapshot.anexos" :key="attachment.hash"><span><strong>{{ attachment.nome }}</strong><small>{{ bytes(attachment.bytes) }} · {{ attachment.hash }}</small></span><button type="button" class="secondary" :disabled="downloading!==null||saving" @click="downloadAttachment(index)">{{ downloading===index?'Baixando…':'Baixar anexo' }}</button></li></ul></section><p v-if="downloadError" role="alert">{{ downloadError }}</p></template><p v-else role="status">Este envio não possui uma prévia disponível. Prepare e revise novamente antes de aprová-lo.</p><section v-if="canApprove||canCancel" class="delivery-actions" aria-label="Ações do envio"><h3>Ações autorizadas</h3><p v-if="canApprove">A aprovação envia o hash desta prévia ao servidor, que reconfere versão, destinatário, aplicabilidade e anexos.</p><button v-if="canApprove" type="button" class="primary" :disabled="saving" @click="ask('approve')">Aprovar e colocar na fila</button><button v-if="canCancel" type="button" class="danger-button" :disabled="saving" @click="ask('cancel')">Cancelar envio</button></section><section v-if="confirmation" class="delivery-confirmation"><p>{{ confirmation==='approve'?'Confirmo que conferi esta prévia e desejo colocá-la na fila.':'Confirmo o cancelamento deste envio.' }}</p><label class="confirmation-check"><input v-model="confirmed" type="checkbox" :disabled="saving"> Confirmo esta ação</label><p v-if="actionError" role="alert">{{ actionError }}</p><footer><button type="button" class="secondary" :disabled="saving" @click="confirmation=null;confirmed=false">Voltar</button><button type="button" :class="confirmation==='approve'?'primary':'danger-button'" :disabled="saving||!confirmed" @click="applyAction">{{ saving?'Salvando…':confirmation==='approve'?'Confirmar aprovação':'Confirmar cancelamento' }}</button></footer></section></AppDialog>
</section></template>

<style scoped>
.deliveries-heading,.delivery-results,.delivery-detail-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.deliveries-heading h2,.delivery-detail-heading h3{margin:4px 0 8px}.deliveries-heading p,.delivery-results p,.delivery-detail-heading p{margin:0;color:var(--muted)}.delivery-summary,.delivery-detail-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:24px 0}.delivery-summary article,.delivery-detail-grid article{min-width:0;padding:16px;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface)}.delivery-summary small,.delivery-detail-grid small,.delivery-attachments small{display:block;color:var(--muted)}.delivery-summary strong{display:block;margin-top:8px;font-size:1.5rem;font-variant-numeric:tabular-nums}.delivery-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr));margin:16px 0}.delivery-detail-grid p{margin:6px 0 0}.delivery-version{overflow-wrap:anywhere}.delivery-detail-warning,.delivery-confirmation{padding:12px;border-radius:var(--radius-control);background:color-mix(in srgb,var(--warning) 12%,transparent)}.delivery-preview-meta{display:grid;grid-template-columns:auto 1fr;gap:8px 16px}.delivery-preview-meta dt{font-weight:700}.delivery-preview-meta dd{margin:0;overflow-wrap:anywhere}.delivery-preview-text{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--surface-muted);font:inherit}.delivery-attachments{display:grid;gap:10px;padding:0;list-style:none}.delivery-attachments li{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:var(--radius-control)}.delivery-attachments strong{display:block;overflow-wrap:anywhere}.delivery-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:20px;padding-top:16px;border-top:1px solid var(--line)}.delivery-actions h3,.delivery-actions p{width:100%;margin:0}.delivery-confirmation{margin-top:16px}.delivery-confirmation footer{display:flex;justify-content:flex-end;gap:12px;margin-top:16px}@media(max-width:900px){.delivery-summary{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:560px){.delivery-summary,.delivery-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.delivery-attachments li{align-items:flex-start;flex-direction:column}}
</style>
